import React from "react";
import ProfessionalCard from "../components/ProfessionalCard";
import p1 from "../assets/p1.jpg";
import p2 from "../assets/p2.jpg";
import p3 from "../assets/p3.jpg";
import p4 from "../assets/p4.jpg";
import p5 from "../assets/p5.jpg";
import p6 from "../assets/p6.jpg";
import "./Hire.css";

export default function Hire() {
  const professionals = [
    { name: "Rahul Singh", skill: "Electrician", img: p1 },
    { name: "Amit Kumar", skill: "Plumber", img: p2 },
    { name: "Sneha Jain", skill: "Cleaner", img: p3 },
    { name: "Anita Sharma", skill: "House Painter", img: p4 },
    { name: "Vikram Reddy", skill: "Appliance Repair", img: p5 },
    { name: "Priya Verma", skill: "Gardener", img: p6 }
  ];

  return (
    <div className="page">
      <h1>Hire Professionals</h1>

      <div className="pro-grid">
        {professionals.map((pro, index) => (
          <div key={index} className="pro-card">
            <ProfessionalCard name={pro.name} skill={pro.skill} img={pro.img} />
            <button className="hire-btn">Hire</button>
          </div>
        ))}
      </div>
    </div>
  );
}
